# ---- 510 Communication Sciences and Disorders I ----
H('510.d.1.A',3,"Communication is the exchange of information, while the sounds a person produces with the mouth to form words are called:","speech",["hearing","grammar","print"],"Speech is sound production.")
H('510.d.1.A',4,"The system of rules and symbols used to share meaning, whether spoken, written, or signed, is called:","language",["breathing","posture","vision"],"Language is a rule system.")
H('510.d.1.B',3,"The vocal folds sit inside the voicebox, which is also called the:","larynx",["pharynx","trachea","esophagus"],"Larynx houses the vocal folds.")
H('510.d.1.B',4,"The part of the ear that holds the cochlea is the:","inner ear",["outer ear","earlobe","ear canal"],"The cochlea is in the inner ear.")
H('510.d.1.C',3,"The structures used to shape sounds into speech, such as the tongue, lips, and jaw, are called:","articulators",["resonators","vibrators","amplifiers"],"Articulators shape sound.")
H('510.d.1.C',4,"The speech system includes breathing, voice production, resonance, and:","articulation",["digestion","circulation","reproduction"],"Four speech subsystems.")
H('510.d.1.D',3,"Sound waves travel through the ear canal and strike a thin membrane called the:","eardrum",["cochlea","retina","larynx"],"Tympanic membrane vibrates.")
H('510.d.1.D',4,"The three tiny bones in the middle ear are the malleus, incus, and:","stapes",["tibia","femur","radius"],"Ossicles carry vibrations.")
H('510.d.1.E',3,"Eye contact, gestures, and facial expressions are forms of:","nonverbal communication",["verbal fluency","written language","phonology"],"Nonverbal cues.")
H('510.d.1.E',4,"A baby's cooing and babbling are early steps in healthy verbal:","development",["decline","loss","silence"],"Babbling precedes words.")
H('510.d.1.F',3,"Before a child can talk, the child must be able to hear, pay attention, and take turns, which are called communication:","prerequisites",["penalties","symptoms","diagnoses"],"Building blocks come first.")
H('510.d.1.F',4,"Looking at a caregiver and passing sounds back and forth is an early form of:","turn-taking",["reading","spelling","writing"],"Turn-taking builds conversation.")
H('510.d.1.G',3,"The study of the sounds of language is called:","phonology",["syntax","semantics","pragmatics"],"Phonology = sound system.")
H('510.d.1.G',4,"The study of word meaning in language is called:","semantics",["phonology","morphology","audiology"],"Semantics = meaning.")
H('510.d.1.H',3,"Using language in social situations, such as greeting someone or taking turns in a talk, is called:","pragmatics",["syntax","phonetics","anatomy"],"Pragmatics = social language.")
H('510.d.1.H',4,"A person's confidence and emotional state can affect how they communicate, which shows the link between communication and:","psychology",["geology","botany","astronomy"],"Psychological bases.")
H('510.d.2.A',3,"The theory that children learn language by imitating adults and being rewarded is the behaviorist view, associated with:","B.F. Skinner",["Noam Chomsky","Jean Piaget","Lev Vygotsky"],"Skinner proposed learning by reinforcement.")
H('510.d.2.A',4,"The theory that humans are born with an inborn ability to learn grammar was proposed by:","Noam Chomsky",["B.F. Skinner","Ivan Pavlov","Sigmund Freud"],"Chomsky's nativist theory.")
H('510.d.2.B',3,"A theory that says children simplify adult sounds using natural patterns is called:","natural phonology",["behaviorism","humanism","realism"],"Natural phonology.")
H('510.d.2.B',4,"Models of speech sound production try to explain how children organize and produce the sounds of their:","language",["homework","toys","pets"],"Speech sound theories.")
H('510.d.2.C',3,"A child with strong spoken language skills is often better prepared to learn to:","read",["swim","drive","vote"],"Language supports literacy.")
H('510.d.2.C',4,"Difficulty with speech sounds in preschool can later affect the ability to connect sounds with letters, which is called:","phonics",["geometry","history","chemistry"],"Sound-letter links.")
H('510.d.3.A',3,"The study of how speech sounds are produced by the mouth and throat is called articulatory:","phonetics",["geometry","chemistry","grammar"],"Phonetics.")
H('510.d.3.A',4,"A sound made with both lips, such as /p/ or /b/, is called:","bilabial",["glottal","velar","dental"],"Bilabial = two lips.")
H('510.d.3.B',3,"Hearing sounds clearly in early childhood is the foundation for learning to produce:","speech sounds",["math facts","dance steps","colors"],"Auditory feedback shapes speech.")
H('510.d.3.B',4,"A child with a hearing loss may have trouble with speech because the child cannot clearly hear the sounds to:","imitate",["measure","draw","weigh"],"Hearing guides imitation.")
H('510.d.3.C',3,"Infants make crying and cooing sounds and later babble, which are early stages of:","vocal development",["hearing loss","reading","handwriting"],"Prespeech development.")
H('510.d.3.C',4,"Repeating syllables like 'bababa' is called:","canonical babbling",["jargon","echolalia only","stuttering"],"Babbling stage.")
H('510.d.3.D',3,"Vowels are important in early speech because they carry much of the sound of a:","word",["ruler","coin","map"],"Vowels are the sound core.")
H('510.d.3.D',4,"Young children usually produce vowels accurately before they produce most:","consonants",["gestures","numbers","pictures"],"Vowels come first.")
H('510.d.3.E',3,"A vowel that glides from one position to another, such as in the word 'boy,' is a:","diphthong",["fricative","plosive","nasal"],"Diphthongs move.")
H('510.d.3.E',4,"Vowels can be described by tongue height, tongue position, and lip:","rounding",["color","price","weight"],"Vowel features.")
H('510.d.3.F',3,"The set of consonant sounds a child can produce is the child's consonant:","inventory",["calendar","budget","menu"],"Inventory = sounds a child can make.")
H('510.d.3.F',4,"Sounds like /m/, /n/, /p/, /b/, and /h/ are usually among the first consonants children:","acquire",["lose","forget","avoid"],"Early sounds.")
H('510.d.3.G',3,"Consonants are described by place, manner, and:","voicing",["spelling","volume only","color"],"Place-manner-voicing.")
H('510.d.3.G',4,"The sound /s/ is a fricative because the air is forced through a narrow:","opening",["bone","wall","gap in a book"],"Fricative = friction.")
H('510.d.3.H',3,"As children develop, they begin combining sounds into syllables and then into:","words",["colors","songs only","numbers"],"Sound sequencing.")
H('510.d.3.H',4,"Replacing a hard sound with an easier one, such as saying 'wabbit' for 'rabbit,' is a normal speech:","process",["disease","injury","habit of adults"],"Phonological process.")
H('510.d.3.I',3,"A child who speaks Spanish at home may use sound patterns that differ from English, which reflects the influence of the:","heritage language",["weather","calendar","school bus"],"Native language influence.")
H('510.d.3.I',4,"Speech differences caused by a home language are considered a language difference, not a speech:","disorder",["advantage","talent","award"],"Difference is not disorder.")
H('510.d.4.A',3,"The components of language include phonology, morphology, syntax, semantics, and:","pragmatics",["geometry","botany","chemistry"],"Five parts of language.")
H('510.d.4.A',4,"The rules for putting words in order to form sentences are called:","syntax",["phonology","semantics","prosody"],"Syntax = word order.")
H('510.d.4.B',3,"The words a person knows and uses make up the person's:","vocabulary",["posture","diet","schedule"],"Vocabulary.")
H('510.d.4.B',4,"The smallest unit of meaning in a language, such as the prefix 'un-', is a:","morpheme",["phoneme","syllable","letter"],"Morphemes carry meaning.")
H('510.d.4.C',3,"Paying attention to a speaker and understanding simple words are skills a child needs before talking, called language:","prerequisites",["penalties","symptoms","results"],"Prerequisite skills.")
H('510.d.4.C',4,"Pointing to show an adult something is an early skill called joint:","attention",["recess","breath","fluency"],"Joint attention.")
H('510.d.4.D',3,"A child whose language skills are developing slowly but in the usual order has a language:","delay",["difference","preference","habit"],"Delay.")
H('510.d.4.D',4,"A language pattern that differs because of a family's dialect or culture, with no problem in learning, is a language:","difference",["disorder","deficit","disease"],"Difference.")
H('510.d.4.E',3,"Most children say their first words at around:","12 months",["2 months","5 years","8 years"],"First words near age 1.")
H('510.d.4.E',4,"By about age 2, most children begin combining two words, such as 'more milk,' which is called a:","two-word phrase",["paragraph","story","poem"],"Two-word combinations.")
H('510.d.4.F',3,"By kindergarten, children typically use complete sentences and understand many more:","words",["recipes","coins","maps"],"Kindergarten language.")
H('510.d.4.F',4,"In elementary school, children learn to use language for reading, writing, and telling:","narratives",["jokes only","secrets only","numbers only"],"Narratives develop.")
H('510.d.4.G',3,"During adolescence, language use grows to include more abstract words, slang, and understanding of:","figurative language",["baby talk","lullabies","nursery rhymes"],"Teen language.")
H('510.d.4.G',4,"A teen using different language with friends than with teachers shows the ability to switch:","registers",["hairstyles","schedules","desks"],"Register shift.")
H('510.d.4.H',3,"Different cultural backgrounds can influence how children learn to tell stories and take turns in:","conversation",["gymnastics","swimming","sleeping"],"Cultural differences.")
H('510.d.4.H',4,"A clinician evaluating a bilingual child should compare the child's skills with those of other children from a similar:","language background",["height","hair color","shoe size"],"Fair comparison.")
H('510.d.5.A',3,"Smooth, easy flow of speech is called verbal:","fluency",["delay","stuttering","pitch"],"Fluency.")
H('510.d.5.A',4,"Repeating sounds, syllables, or words, or blocking on a sound, are called:","disfluencies",["vowels","dialects","phrases"],"Disfluencies.")
H('510.d.5.B',3,"A child who repeats whole words or phrases such as 'I want, I want' is showing a typical disfluency type called:","repetition",["blocking","prolongation","silence"],"Normal disfluency.")
H('510.d.5.B',4,"Many children go through a period of increased disfluency at about age 2 to 5 while their language is:","growing quickly",["shrinking","fixed","absent"],"Developmental disfluency.")
H('510.d.5.C',3,"Children learn to put sounds together and then to build sentences, a process called speech and language:","development",["decay","loss","failure"],"Skills develop.")
H('510.d.5.C',4,"A child's speech becomes easier for strangers to understand as the child's sound system:","matures",["shrinks","freezes","vanishes"],"Intelligibility improves.")
H('510.d.5.D',3,"Feeling nervous or talking very fast can make speech less:","fluent",["loud","long","clear to see"],"Variables affect fluency.")
H('510.d.5.D',4,"Stress, speaking rate, and sentence length are variables that may affect verbal:","fluency",["height","vision","taste"],"Fluency variables.")
H('510.d.5.E',3,"To measure the fluency of an English language learner, a clinician must consider the speaker's:","language experience",["favorite food","clothing","height"],"ELL fluency.")
H('510.d.5.E',4,"A bilingual child's disfluencies may differ in each language because of different levels of:","proficiency",["weight","hobbies","age at birth"],"Proficiency affects fluency.")
H('510.d.6.A',3,"Voice is produced when air from the lungs makes the vocal folds:","vibrate",["freeze","dry out","turn white"],"Vocal fold vibration.")
H('510.d.6.A',4,"The highness or lowness of a voice is its:","pitch",["rate","volume","rhythm"],"Pitch.")
H('510.d.6.B',3,"A healthy voice has good quality, appropriate pitch, and appropriate:","loudness",["color","weight","height"],"Healthy voice features.")
H('510.d.6.B',4,"The way the sound from the vocal folds is shaped by the throat, mouth, and nose is called:","resonance",["rhythm","pitch","tempo"],"Resonance.")
H('510.d.6.C',3,"Yelling and overusing the voice can cause growths on the vocal folds called:","nodules",["cavities","blisters","freckles"],"Vocal nodules.")
H('510.d.6.C',4,"Reflux, smoking, and dehydration are all causes of changes in voice:","quality",["color","length","spelling"],"Voice variation causes.")
H('510.d.6.D',3,"During puberty, a boy's voice becomes lower as the larynx:","grows larger",["shrinks","moves away","stops working"],"Pubertal change.")
H('510.d.6.D',4,"In older adults, the voice may become weaker or more breathy because the vocal folds become less:","firm",["wet","blue","long"],"Aging voice.")
H('510.d.6.E',3,"Dry air, loud noise, and pollution are examples of environmental variables that can strain the:","voice",["eyes","feet","knees"],"Environment affects voice.")
H('510.d.6.E',4,"Teachers and singers who talk loudly all day are at higher risk for voice:","problems",["promotions","lessons","awards"],"Vocal demands.")
H('510.d.6.F',3,"A speech-language pathologist must have a state license and usually a master's degree, which defines the practice and allowable:","services",["vacations","hairstyles","menus"],"Scope of practice.")
H('510.d.6.F',4,"A speech-language pathologist may work with people of all ages in schools, hospitals, and:","clinics",["airports","farms only","stadiums"],"Work settings.")
H('510.d.6.G',3,"Keeping a client's information private is part of the ethical duty of:","confidentiality",["advertising","speed","fashion"],"Confidentiality.")
H('510.d.6.G',4,"A speech-language pathologist should provide only the services that he or she is qualified, meaning working within the limits of:","competence",["luck","budget","rumors"],"Competence.")
H('510.d.7.A',3,"A child who says a word that others can understand, such as 'ba' for 'ball,' is usually about:","12 to 18 months old",["5 to 6 years old","10 years old","15 years old"],"Early word milestones.")
H('510.d.7.A',4,"Children with typical development usually ask 'what' and 'where' questions by about age:","2 to 3",["5 months","8 to 9","12"],"Question milestones.")
H('510.d.7.B',3,"Language milestones may be compared with the milestones of motor, social, and thinking:","development",["fashion","sports","cooking"],"Development domains.")
H('510.d.7.B',4,"Delays in language together with delays in walking or thinking may mean a broader developmental:","concern",["celebration","holiday","trend"],"Related areas.")
H('510.d.7.C',3,"Language used to chat with friends and family is called basic interpersonal communication, while language used for school learning is:","academic language",["slang only","baby talk","secret code"],"BICS and CALP.")
H('510.d.7.C',4,"It usually takes English language learners longer to develop the language needed for school than for:","everyday conversation",["sleeping","playing alone","sports only"],"Social language comes first.")
H('510.d.7.D',3,"Everyday words like 'dog' and 'happy' are tier 1 vocabulary, while subject-specific words like 'photosynthesis' are tier:","3",["1","0","7"],"Tier 3 is technical.")
H('510.d.7.D',4,"Tier 2 words are general academic words used across subjects, such as:","analyze",["dog","cat","table"],"Tier 2 examples.")
H('510.d.7.E',3,"The ability to tell a story with a beginning, middle, and end shows the development of:","narrative language",["hearing","balance","grip"],"Narrative development.")
H('510.d.7.E',4,"Written narratives usually develop after:","oral narratives",["birth","walking","reading never"],"Oral comes first.")
H('510.d.7.F',3,"Skills such as greeting people, staying on topic, and taking turns are part of:","pragmatic language",["voice quality","hearing tests","motor skills"],"Pragmatics.")
H('510.d.7.F',4,"A child who stands too close and talks about only one topic may have a pragmatic language:","difficulty",["advantage","award","habit of sleeping"],"Pragmatic problems.")
H('510.d.7.G',3,"Skills that come before reading and writing, such as recognizing letters and rhymes, make up emergent:","literacy",["numeracy","athletics","geography"],"Emergent literacy.")
H('510.d.7.G',4,"Knowing that spoken words can be broken into separate sounds, a skill that helps with rhyming and reading, is called phonological:","awareness",["delay","loss","blockage"],"Phonological awareness.")
H('510.d.8.A',3,"A speech-language pathologist helps decide whether a child's communication is healthy or shows a:","disorder",["birthday","vacation","holiday"],"SLP role.")
H('510.d.8.A',4,"An SLP can diagnose communication disorders, but cannot diagnose a:","hearing loss medically",["speech sound disorder","language disorder","fluency disorder"],"Scope boundary.")
H('510.d.8.B',3,"A quick check to decide whether a child needs a full evaluation is called a:","screening",["diagnosis","treatment","discharge"],"Screening.")
H('510.d.8.B',4,"A screening that shows a possible problem leads to a referral for a full:","evaluation",["vacation","party","contest"],"Screen then evaluate.")
H('510.d.8.C',3,"A full assessment that measures speech, language, and related skills is a(n):","evaluation",["screening","lesson","recess"],"Evaluation.")
H('510.d.8.C',4,"Evaluations often include standardized tests, observation, and a case:","history",["menu","budget","song"],"Evaluation components.")
H('510.d.8.D',3,"In Response to Intervention, students receive more support as they move through increasing:","tiers",["grades only","vacations","pets"],"RtI tiers.")
H('510.d.8.D',4,"RtI helps schools tell whether a child's difficulty is due to a disability or to a lack of:","adequate instruction",["height","money","age"],"RtI purpose.")
H('510.d.8.E',3,"When an SLP finds a problem outside the SLP's scope, the SLP makes a:","referral",["menu","joke","recipe"],"Referral.")
H('510.d.8.E',4,"An SLP shares evaluation results with a family and explains them in a process called:","counseling",["advertising","grading","coding"],"Counseling families.")
H('510.d.9.A',3,"When talking with a client, an SLP should use language that fits the client's age and:","understanding",["height","pay","mood only"],"Appropriate language.")
H('510.d.9.A',4,"Making eye contact, listening, and using a calm voice are examples of appropriate communication when working with:","clients",["machines","furniture","tools only"],"Client interaction.")
H('510.d.9.B',3,"Nodding, smiling, and facing the speaker are examples of:","nonverbal techniques",["verbal fluency","phonetics","syntax"],"Nonverbal skills.")
H('510.d.9.B',4,"Repeating back what a client has said to show understanding is called:","paraphrasing",["interrupting","ignoring","assuming"],"Paraphrasing.")
H('510.d.9.C',3,"A device that speaks words when a user presses a symbol is an example of augmentative and alternative communication, called:","AAC",["MRI","EKG","AED"],"AAC.")
H('510.d.9.C',4,"A tablet app that lets a nonspeaking child choose pictures to make requests is a form of:","assistive technology",["x-ray","surgery","medication"],"Assistive tech.")
H('510.d.9.D',3,"Changing spoken words from one language to another as the words are spoken is:","interpretation",["translation","editing","grading"],"Interpretation is oral.")
H('510.d.9.D',4,"Changing written text from one language to another is:","translation",["interpretation","editing","grading"],"Translation is written.")
H('510.d.10.A',3,"Different dialects can express the same idea with different words or grammar, while still being valid forms of:","English",["math","music","art only"],"Dialect variety.")
H('510.d.10.A',4,"Saying 'He is going' in Standard American English and 'He be going' in another dialect shows dialectal:","variation",["error","disease","disorder"],"Variation.")
H('510.d.10.B',3,"Speech and language patterns can vary by language, region, and:","culture",["height","blood type","shoe size"],"Variation sources.")
H('510.d.10.B',4,"A person who speaks two languages may mix them, which is called code:","switching",["breaking","locking","freezing"],"Code-switching.")
H('510.d.10.C',3,"African American English, Southern English, and Appalachian English are examples of American English:","dialects",["disorders","diseases","errors"],"Dialects.")
H('510.d.10.C',4,"Dialects have their own rules for sounds and grammar, so they should be treated as rule-governed language:","varieties",["errors","mistakes","defects"],"Dialects are rule-governed.")
H('510.d.10.D',3,"A speaker whose first language lacks a certain English sound may replace it with a sound from the:","heritage language",["weather","calendar","clock"],"Transfer.")
H('510.d.10.D',4,"A Spanish speaker may say 'eschool' for 'school' because Spanish words do not begin with:","s plus consonant",["vowels","m sounds","t sounds"],"Transfer patterns.")
H('510.d.10.E',3,"English language learners may show errors that reflect the rules of their first language, which are not signs of a language:","disorder",["gift","skill","dialect"],"Not disorder.")
H('510.d.10.E',4,"When assessing an English language learner, the SLP should evaluate skills in both English and the child's:","home language",["favorite game","school lunch","bus route"],"Assess both languages.")

# ---- 511 Communication Sciences and Disorders II ----
H('511.d.1.A',3,"The nerves and brain areas that carry signals for speech and hearing make up the peripheral and central:","nervous systems",["skeletal systems","digestive systems","muscular systems only"],"Neural basis of communication.")
H('511.d.1.A',4,"The part of the brain most involved in producing speech, located in the left frontal lobe, is called:","Broca's area",["Wernicke's area","the cerebellum","the brainstem"],"Broca's area produces speech.")
H('511.d.1.B',3,"The physical property of sound that we hear as how high or low it is, measured in hertz, is its:","frequency",["intensity","duration","timbre"],"Frequency relates to pitch.")
H('511.d.1.B',4,"The intensity of a sound, which we perceive as loudness, is measured in:","decibels",["hertz","watts","inches"],"Decibels measure loudness.")
H('511.d.1.C',3,"Hearing loss caused by a problem in the outer or middle ear is called:","conductive",["sensorineural","central","mixed only"],"Conductive loss.")
H('511.d.1.C',4,"Hearing loss caused by damage to the cochlea or auditory nerve is called:","sensorineural",["conductive","external","temporary only"],"Sensorineural loss.")
H('511.d.1.D',3,"Children with untreated hearing loss often have delays in speech and:","language",["height","weight","vision"],"Hearing loss delays language.")
H('511.d.1.D',4,"Early identification of hearing loss is important because the first few years are critical for language:","development",["decline","retirement","loss"],"Early intervention.")
H('511.d.1.E',3,"Communication skills change across the lifespan, so comparing speech and language in children and older adults shows how they change over:","time",["color","size","price"],"Lifespan changes.")
H('511.d.1.E',4,"Older adults may have trouble hearing high-pitched sounds due to age-related hearing loss called:","presbycusis",["tinnitus","otitis","vertigo"],"Presbycusis.")
H('511.d.1.F',3,"Speech disorders involve how sounds are made, while language disorders involve understanding or using:","words and sentences",["only gestures","only volume","only pitch"],"Speech vs language.")
H('511.d.1.F',4,"A person with a hearing disorder may also have difficulty with speech and language because hearing supports:","communication",["digestion","balance only","breathing only"],"Related disorders.")
H('511.d.1.G',3,"Problems with the production of speech sounds, fluency, or voice are called speech:","disorders",["talents","styles","rules"],"Speech disorders.")
H('511.d.1.G',4,"Difficulty understanding or using words and grammar is called a language:","disorder",["talent","strength","preference"],"Language disorder.")
H('511.d.1.H',3,"When a family needs an interpreter, a barrier can arise when the interpreter does not know the right medical:","terms",["colors","songs","maps"],"Interpreter barriers.")
H('511.d.1.H',4,"Using a trained professional interpreter rather than a child family member helps protect accuracy and:","privacy",["speed","fashion","volume"],"Professional interpreters.")
H('511.d.2.A',3,"In children, a common cause of temporary hearing loss is fluid in the middle ear from ear:","infections",["haircuts","exercises","meals"],"Otitis media.")
H('511.d.2.A',4,"In adults, a common cause of hearing loss is long-term exposure to loud:","noise",["light","water","air"],"Noise-induced loss.")
H('511.d.2.B',3,"A stroke can cause a language disorder called:","aphasia",["dyslexia","anemia","asthma"],"Aphasia.")
H('511.d.2.B',4,"Damage to the brain from a head injury can cause problems with speech, language, and:","memory",["height","eye color","hair growth"],"TBI effects.")
H('511.d.2.C',3,"A child who has trouble pronouncing sounds beyond the typical age may have a speech sound:","disorder",["gift","habit","hobby"],"Speech sound disorder.")
H('511.d.2.C',4,"A common symptom of a language disorder in a child is limited:","vocabulary",["height","hair","appetite"],"Language symptoms.")
H('511.d.2.D',3,"A communication disorder can affect a person's school performance, friendships, and:","self-esteem",["height","blood type","eye color"],"Impact on the person.")
H('511.d.2.D',4,"Adults with communication disorders may struggle at work because it is harder to share ideas and follow:","directions",["trends","seasons","recipes"],"Functional impact.")
H('511.d.2.E',3,"Different cultures may view communication disorders differently, so clinicians must show cultural:","sensitivity",["rigidity","bias","pride"],"Cultural variation.")
H('511.d.2.E',4,"A family that believes a delay will resolve on its own may wait longer to seek help, which shows how culture can affect:","help-seeking",["height","weather","diet only"],"Cultural attitudes.")
H('511.d.3.A',3,"A child who deletes final sounds, such as saying 'ca' for 'cat,' is showing a phonological:","process",["talent","accent","gift"],"Phonological process.")
H('511.d.3.A',4,"Speech sound disorders may involve articulation errors or a pattern problem in the child's phonological:","system",["diet","vision","posture"],"Articulation vs phonology.")
H('511.d.3.B',3,"A therapy approach in which the clinician teaches a child to produce a target sound through repeated practice is:","traditional articulation therapy",["medication","surgery","hypnosis"],"Articulation therapy.")
H('511.d.3.B',4,"A treatment that targets patterns of sound errors, such as the cycles approach, is used for phonological:","disorders",["talent","growth","strength"],"Phonological treatment.")
H('511.d.3.C',3,"Stuttering may include repetitions, prolongations, blocks, and secondary behaviors such as:","eye blinking",["singing","whistling","clapping"],"Secondary characteristics.")
H('511.d.3.C',4,"Behaviors that people who stutter use to escape or avoid stuttering are called:","secondary behaviors",["primary sounds","vowels","phonemes"],"Secondary characteristics.")
H('511.d.3.D',3,"A treatment approach that teaches speaking with easy onset and slower speech to reduce stuttering is called fluency:","shaping",["stopping","reading","printing"],"Fluency shaping.")
H('511.d.3.D',4,"The Lidcombe Program is an evidence-based treatment for stuttering in:","young children",["older adults only","infants only","teenagers only"],"Lidcombe.")
H('511.d.3.E',3,"A hoarse or breathy voice is a problem with vocal:","quality",["meaning","color","spelling"],"Voice quality.")
H('511.d.3.E',4,"A voice that is too loud or too soft is a disorder of vocal:","volume",["quality","pitch","resonance"],"Volume.")
H('511.d.3.F',3,"Rest, hydration, and reducing vocal strain are part of a plan to treat voice disorders using vocal:","hygiene",["fashion","speed","color"],"Vocal hygiene.")
H('511.d.3.F',4,"A voice treatment plan should be based on evidence and should include a medical referral to an:","ENT physician",["dentist only","chef","coach"],"ENT referral.")
H('511.d.3.G',3,"Using wrong word order or leaving out word endings in a child's sentences shows difficulty with syntax and:","morphology",["phonology","audiology","anatomy"],"Language form.")
H('511.d.3.G',4,"A child who struggles to understand questions and directions has a problem with receptive:","language",["voice","fluency","hearing aids"],"Receptive language.")
H('511.d.3.H',3,"Treatment that gives a child focused language practice in play and conversation is a language:","intervention",["vacation","penalty","holiday"],"Language intervention.")
H('511.d.3.H',4,"Treatment decisions for language disorders should be guided by research evidence, clinical expertise, and client:","values",["luck","fashion","hair color"],"EBP components.")
H('511.d.4.A',3,"When speaking with a client, a clinician should choose communication skills that fit the age and the:","situation",["weather","color","price"],"Situation-appropriate communication.")
H('511.d.4.A',4,"Using simple words and short sentences with a young child helps the child:","understand",["forget","avoid","sleep"],"Match language.")
H('511.d.4.B',3,"Facing a client and using open body language are examples of effective:","nonverbal communication",["verbal fluency","phonology","syntax"],"Nonverbal.")
H('511.d.4.B',4,"A clinician who nods and says 'I see' is showing active:","listening",["speaking","reading","writing"],"Active listening.")
H('511.d.4.C',3,"A clinician may use video calls to provide therapy from a distance, which is called:","teletherapy",["surgery","dialysis","imaging"],"Teletherapy.")
H('511.d.4.C',4,"When using electronic communication with clients, a clinician must protect the client's:","confidentiality",["advertising","speed","fashion"],"Privacy online.")
H('511.d.5.A',3,"Speech and language patterns vary based on language, region, and cultural:","background",["height","weight","fashion"],"Variation.")
H('511.d.5.A',4,"A clinician must not call a dialect difference a disorder because dialects are:","rule-governed",["errors","diseases","defects"],"Dialects.")
H('511.d.5.B',3,"In a simulated interview with a child's parent, the clinician should ask about the child's:","developmental history",["favorite color","hair length","shoe size"],"Case history.")
H('511.d.5.B',4,"During a family interview, a clinician should use plain language and avoid:","jargon",["questions","greetings","listening"],"Plain language.")
H('511.d.5.C',3,"Some cultures prefer indirect communication or avoid direct eye contact as a sign of:","respect",["rudeness only","illness","anger"],"Cultural patterns.")
H('511.d.5.C',4,"Understanding that a family values group decisions helps a clinician provide care that is culturally:","sensitive",["rigid","careless","strict"],"Cultural fit.")
H('511.d.5.D',3,"Care that involves the family in setting goals and making decisions is called family-centered:","practice",["entertainment","fashion","reward"],"Family-centered care.")
H('511.d.5.D',4,"A culturally sensitive plan respects the family's values, language, and:","traditions",["height","hair color","shoe size"],"Cultural respect.")
H('511.d.5.E',3,"A child who is learning English and speaking it with an accent has a language:","difference",["disorder","delay","deficit"],"Language difference.")
H('511.d.5.E',4,"A language disorder differs from a language difference because a disorder appears in all the child's:","languages",["birthdays","classes only","meals"],"Disorder across languages.")
H('511.d.6.A',3,"A hearing test that presents tones at different frequencies to find the softest sounds a person can hear is called:","pure-tone audiometry",["tympanometry","otoscopy","x-ray"],"Audiometry.")
H('511.d.6.A',4,"The results of a hearing test are plotted on a graph called an:","audiogram",["histogram","diagram of a cell","pie chart"],"Audiogram.")
H('511.d.6.B',3,"A basic hearing screening checks whether a person responds to tones at a set level, such as 20 or 25:","decibels",["hertz","pounds","degrees"],"Screening level.")
H('511.d.6.B',4,"Before screening, the clinician checks the ear canal with an otoscope to look for:","blockage",["eye color","height","weight"],"Otoscopy.")
H('511.d.6.C',3,"A screening for speech sound production checks whether a child can say sounds correctly for the child's:","age",["height","weight","eye color"],"Age-appropriate sounds.")
H('511.d.6.C',4,"A fluency screening listens for repetitions, prolongations, and:","blocks",["colors","songs","maps"],"Fluency screening.")
H('511.d.6.D',3,"A developmental screening checks several areas, including speech, language, and:","motor skills",["income","address","hair color"],"Developmental screening.")
H('511.d.6.D',4,"A screening tool should be accurate and appropriate for the child's age and:","language",["height","weight","grade only"],"Valid tools.")
H('511.d.6.E',3,"A diagnostic report should include the reason for referral, case history, test results, and:","recommendations",["recipes","jokes","songs"],"Report components.")
H('511.d.6.E',4,"The part of a report that tells the reader the clinician's conclusion about the findings is the:","impression",["title","date","address"],"Impression.")
H('511.d.7.A',3,"Evidence-based practice combines research evidence, clinical expertise, and client:","preferences",["secrets","pay","weight"],"EBP.")
H('511.d.7.A',4,"Scientific research is one part of evidence-based practice but EBP also uses the clinician's experience and the client's:","values",["height","weight","age only"],"EBP is broader than research.")
H('511.d.7.B',3,"The American Speech-Language-Hearing Association rates the strength of research using evidence:","levels",["colors","flavors","prices"],"Evidence levels.")
H('511.d.7.B',4,"Studies with a stronger design, such as randomized trials, receive a higher level of:","evidence",["noise","humor","color"],"Stronger designs rank higher.")
H('511.d.7.C',3,"A clinician reads a research study and decides how strong its evidence is, which is called:","appraising the study",["ignoring the study","deleting the study","hiding the study"],"Appraisal.")
H('511.d.7.C',4,"A single case report generally provides weaker evidence than a:","randomized controlled trial",["rumor","guess","personal opinion"],"Level of evidence.")
H('511.d.7.D',3,"Expert opinion is useful, but it is usually considered a lower level of evidence than:","well-designed research",["rumors","guesses","advertisements"],"Opinion ranking.")
H('511.d.7.D',4,"Clinical experience helps a clinician apply research findings to an:","individual client",["empty room","machine","poster"],"Clinical judgment.")
H('511.d.7.E',3,"A project in which a clinician tests a new approach in his or her own practice and records the results is called action:","research",["fiction","drama","comedy"],"Action research.")
H('511.d.7.E',4,"After finishing an action research project, a clinician should present the findings to:","colleagues",["no one","machines","nobody at all"],"Share results.")
H('511.d.8.A',3,"Two approaches for treating speech sound disorders are traditional articulation therapy and:","phonological therapy",["surgery","chemotherapy","dialysis"],"Compare approaches.")
H('511.d.8.A',4,"When comparing treatment approaches, a clinician considers evidence, time required, and the child's:","needs",["address","pet","clothing"],"Selection factors.")
H('511.d.8.B',3,"Two approaches for treating stuttering are fluency shaping and:","stuttering modification",["surgery","chemotherapy","dialysis"],"Fluency approaches.")
H('511.d.8.B',4,"Stuttering modification teaches a person to stutter more:","easily",["loudly","often","angrily"],"Modify stuttering.")
H('511.d.8.C',3,"A voice treatment that teaches a client to reduce vocal strain and use healthy habits is called vocal function and vocal:","hygiene",["fashion","decor","shopping"],"Voice treatment.")
H('511.d.8.C',4,"Practicing resonant voice exercises in therapy is an example of voice treatment in a:","clinical setting",["stadium","kitchen","parking lot"],"Practice in settings.")
H('511.d.8.D',3,"Preschool language treatment often uses game-like, parent-involved methods because young children learn best through games and:","play",["lectures","tests","homework"],"Preschool approach.")
H('511.d.8.D',4,"One preschool approach teaches parents to support language during daily routines, called a parent-:","implemented program",["lecture series","exam","penalty"],"Parent training.")
H('511.d.8.E',3,"In elementary school, language treatment often connects goals to the classroom:","curriculum",["menu","parade","budget"],"Curriculum-based.")
H('511.d.8.E',4,"School-age language therapy may target vocabulary, grammar, and the ability to understand and tell:","narratives",["jokes only","numbers only","songs only"],"School-age goals.")
H('511.d.8.F',3,"Children with autism may benefit from treatment for language and social communication, including the use of:","visual supports",["medicine only","surgery","ice"],"Autism support.")
H('511.d.8.F',4,"A child who does not speak may be given a picture exchange system, a type of alternative communication called:","PECS",["MRI","EKG","AED"],"PECS.")

# ---- 512 Nursing Science ----
H('512.d.1.A',3,"To become a registered nurse, a person must complete an accredited nursing program and pass the national licensure exam called:","NCLEX-RN",["SAT","ACT","GED"],"RN licensure.")
H('512.d.1.A',4,"The three common educational paths to becoming an RN are a diploma, an associate degree, and a:","bachelor's degree",["certificate in art","driver's course","coding bootcamp"],"RN pathways.")
H('512.d.1.B',3,"Nurses may work in hospitals, doctors' offices, nursing homes, and:","schools",["airports only","farms only","stadiums only"],"Work settings.")
H('512.d.1.B',4,"A nurse who visits patients in their houses works in:","home health",["radiology","surgery","dietetics"],"Home health setting.")
H('512.d.1.C',3,"To become a certified nursing assistant, a person usually completes a state-approved training program and passes a:","competency exam",["driving test","spelling bee","cooking class"],"CNA requirements.")
H('512.d.1.C',4,"Certified nursing assistants are listed on a state:","registry",["menu","calendar","newspaper"],"CNA registry.")
H('512.d.1.D',3,"A CNA's scope of practice includes bathing, feeding, and taking:","vital signs",["x-rays","surgeries","prescriptions"],"CNA tasks.")
H('512.d.1.D',4,"A CNA is not allowed to perform tasks outside the legal limits set by the state, such as:","prescribing medicine",["bathing a patient","feeding a patient","taking vital signs"],"Outside scope.")
H('512.d.1.E',3,"Workers who help nurses but are not licensed, such as aides, are called unlicensed assistive:","personnel",["pharmacists","physicians","patients"],"UAP.")
H('512.d.1.E',4,"When a nurse delegates a task to UAP, the nurse remains responsible for the:","patient's care",["aide's lunch","parking","uniform choice"],"Delegation accountability.")
H('512.d.1.F',3,"An LPN program usually takes about one year, while an associate degree in nursing usually takes about:","two years",["six months","ten years","one week"],"ADN length.")
H('512.d.1.F',4,"A BSN program usually takes about four years and prepares nurses for broader roles including:","leadership",["plumbing","carpentry","farming"],"BSN breadth.")
H('512.d.1.G',3,"An advanced practice registered nurse needs at least a master's degree and national:","certification",["parking permit","uniform","badge only"],"APRN requirements.")
H('512.d.1.G',4,"Nurse practitioners, clinical nurse specialists, nurse midwives, and nurse anesthetists are all types of:","APRNs",["CNAs","LPNs","EMTs"],"APRN types.")
H('512.d.1.H',3,"A nurse who works with infants and children has chosen a specialty in:","pediatrics",["geriatrics","oncology","cardiology"],"Pediatric nursing.")
H('512.d.1.H',4,"A nurse who cares for very sick patients in an intensive care unit works in:","critical care",["school nursing","public relations","clerical care"],"Critical care.")
H('512.d.2.A',3,"A patient intake interview begins with recording the patient's reason for the visit and:","medical history",["favorite song","shoe size","car model"],"Intake.")
H('512.d.2.B',3,"A head-to-toe assessment uses inspection, palpation, percussion, and:","auscultation",["recitation","negotiation","navigation"],"Physical assessment.")
H('512.d.2.A',4,"During intake, a nurse also asks about allergies and current:","medications",["hobbies","pets","vacations"],"Intake includes meds.")
H('512.d.2.B',4,"During a head-to-toe assessment, a nurse notes any abnormal findings such as a rash, swelling, or:","bruising",["happiness","hunger","humor"],"Abnormal findings.")
H('512.d.2.C',3,"Vital signs include temperature, pulse, respirations, and:","blood pressure",["height","shoe size","hair color"],"Vitals.")
H('512.d.2.C',4,"Vital signs are important because changes may be the first sign that a patient's condition is getting:","worse",["louder","longer","colder only"],"Vitals monitor status.")
H('512.d.2.D',3,"The device used to measure blood pressure is a:","sphygmomanometer",["thermometer","stethoscope","oximeter"],"BP cuff.")
H('512.d.2.D',4,"A nurse listens to heart and lung sounds with a:","stethoscope",["thermometer","scale","ruler"],"Stethoscope.")
H('512.d.2.E',3,"A normal adult resting pulse is about 60 to 100 beats per:","minute",["hour","day","week"],"Normal pulse.")
H('512.d.2.E',4,"A body temperature of 102 degrees Fahrenheit is considered a:","fever",["normal reading","low reading","dangerous cold"],"Fever.")
H('512.d.2.F',3,"The nursing process steps include assessment, diagnosis, planning, implementation, and:","evaluation",["celebration","vacation","competition"],"ADPIE.")
H('512.d.2.F',4,"In the nursing process, setting goals and choosing actions happens during:","planning",["assessment","evaluation","discharge"],"Planning.")
H('512.d.3.A',3,"Activities of daily living include basic tasks like bathing, dressing, and:","eating",["gaming","shopping","driving"],"ADLs.")
H('512.d.3.A',4,"Tasks such as managing money and cooking are called instrumental ADLs, while bathing and dressing are called:","basic ADLs",["leisure","hobbies","chores only"],"ADL types.")
H('512.d.3.B',3,"A nurse assesses a patient's independence by observing how well the patient can do ADLs without:","help",["clothes","food","rest"],"Independence assessment.")
H('512.d.3.B',4,"The Katz Index is a tool that scores a person's independence in:","ADLs",["math","spelling","music"],"Katz Index.")
H('512.d.3.C',3,"A nurse promotes quality of life by encouraging patients to do as much as possible for themselves, which supports their:","independence",["dependence","isolation","boredom"],"Promote function.")
H('512.d.3.C',4,"Helping a patient stay active and involved in meaningful activities supports optimal patient:","function",["decline","delay","debt"],"Function.")
H('512.d.3.D',3,"Depression and anxiety are examples of mental health disorders that can affect a person's ability to do:","daily activities",["math only","art only","music only"],"Mental health and ADLs.")
H('512.d.3.D',4,"A patient who stops eating and bathing because of sadness may need to be screened for:","depression",["asthma","anemia","arthritis"],"Depression screening.")
H('512.d.3.E',3,"A patient with limited arm strength may need an assistive device such as a:","reacher or grab bar",["tuba","skateboard","kite"],"Assistive devices.")
H('512.d.3.E',4,"A nurse recommends a walker for a patient who has trouble with:","balance",["reading","hearing music","tasting"],"Mobility aids.")
H('512.d.3.F',3,"If a patient cannot dress independently, the nurse's care plan should include help with:","dressing",["gaming","traveling","cooking dinner"],"Match care to deficit.")
H('512.d.3.F',4,"A therapeutic care plan for a patient who cannot feed himself would include assistance with:","eating",["driving","shopping","gardening"],"Aligned care.")
H('512.d.4.A',3,"A certification that teaches CPR and use of an AED is called basic life:","support",["style","care","action"],"BLS.")
H('512.d.4.A',4,"The American Red Cross and the American Heart Association are two organizations that offer first aid and:","CPR certification",["cooking classes","flight lessons","art classes"],"First aid certifications.")
H('512.d.4.B',3,"A nurse with first aid and CPR certification can respond more quickly during a medical crisis, known as an:","emergency",["audit","interview","meeting"],"Advantage.")
H('512.d.4.B',4,"Many employers require nurses to keep their CPR certification:","current",["secret","hidden","expired"],"Employer requirement.")
H('512.d.4.C',3,"Pressing firmly on a cut with a clean cloth is a first aid skill used to control blood loss, also called:","bleeding",["hearing","sleeping","thinking"],"Bleeding control.")
H('512.d.4.C',4,"The recommended compression rate for adult CPR is 100 to 120 per:","minute",["hour","second","day"],"CPR rate.")
H('512.d.4.D',3,"In an emergency, a nurse's role includes assessing the patient and calling for:","help",["lunch","pizza","music"],"Emergency role.")
H('512.d.4.D',4,"In an emergency, the nurse stays calm, follows protocol, and communicates clearly with the:","team",["television","radio","stranger"],"Teamwork in emergencies.")
H('512.d.5.A',3,"Equipment used to monitor a patient's heart rhythm is an electrocardiogram, abbreviated:","EKG",["MRI","CPR","IV"],"EKG.")
H('512.d.5.A',4,"A pulse oximeter measures the percentage of oxygen in the patient's:","blood",["urine","hair","skin tone"],"Pulse ox.")
H('512.d.5.B',3,"Maslow's hierarchy lists basic needs such as food, water, and rest at the:","bottom",["top","middle","edge"],"Physiological needs.")
H('512.d.5.B',4,"A nurse uses theories such as Erikson's stages of development to understand patient needs across the:","lifespan",["menu","calendar","budget"],"Lifespan.")
H('512.d.5.C',3,"A patient lying on the back with the head lowered below the feet is in the Trendelenburg position, which is used to:","increase blood flow to the head",["relax the legs","help eat","help sleeping only"],"Trendelenburg.")
H('512.d.5.C',4,"The position with the head of the bed raised 45 to 60 degrees, often used to help breathing and eating, is:","Fowler's position",["supine","prone","Trendelenburg"],"Fowler's.")
H('512.d.5.D',3,"Teaching a patient and family about care at home is called patient:","education",["billing","coding","scheduling"],"Education.")
H('512.d.5.D',4,"A good way to check that a patient understood teaching is to ask the patient to explain it in his or her own:","words",["pictures","songs","dances"],"Teach-back.")
H('512.d.5.E',3,"A walker or cane that helps a patient walk safely is an example of an assistive:","device",["menu","diet","wage"],"Assistive equipment.")
H('512.d.5.E',4,"Before using a walker, a nurse checks that it is the right height for the:","patient",["wall","floor","bed"],"Fit equipment.")
H('512.d.6.A',3,"A digital patient chart is an electronic medical:","record",["recipe","menu","game"],"EMR.")
H('512.d.6.A',4,"Technology that lets a nurse scan a patient's wristband before giving medicine helps prevent:","errors",["sleep","music","games"],"Barcode scanning.")
H('512.d.6.B',3,"A nurse can find a patient's lab results and normal ranges in the electronic:","health record",["menu","calendar","phone book"],"Lab values.")
H('512.d.6.B',4,"Lab results outside normal ranges are called:","abnormal values",["averages","recipes","vitals"],"Abnormal labs.")
H('512.d.6.C',3,"Using devices at home that send a patient's readings to the care team is called remote patient:","monitoring",["relaxing","traveling","dancing"],"Remote monitoring.")
H('512.d.6.C',4,"Visits with a nurse or doctor by video call are called:","telehealth",["radiology","pharmacy","surgery"],"Telehealth.")
H('512.d.7.A',3,"A comprehensive patient assessment includes a health history, a physical exam, and a review of:","medications",["hobbies","vacations","fashion"],"Comprehensive.")
H('512.d.7.A',4,"A nurse uses data from the assessment to identify the patient's health:","needs",["hobbies","wishes","pets"],"Assessment data.")
H('512.d.7.B',3,"Information the patient tells the nurse, such as pain or nausea, is called subjective data, while measurements like blood pressure are:","objective data",["subjective data","opinions","feelings"],"Subjective vs objective.")
H('512.d.7.B',4,"A patient saying 'I feel dizzy' is an example of:","subjective data",["objective data","lab data","vital signs"],"Subjective.")
H('512.d.7.C',3,"Comparing health outcomes in Texas with those across the nation helps identify local health:","trends",["colors","songs","games"],"Compare outcomes.")
H('512.d.7.C',4,"Public health agencies collect data on illness and death rates to identify health:","disparities",["fashions","hobbies","games"],"Health data.")
H('512.d.7.D',3,"A peer-reviewed article has been checked by other experts before it is:","published",["destroyed","hidden","ignored"],"Peer review.")
H('512.d.7.D',4,"Evaluating the efficacy of a treatment in a study means deciding how well it:","works",["looks","sounds","costs"],"Efficacy.")
H('512.d.7.E',3,"A nursing care plan uses the steps assess, diagnose, plan, implement, and:","evaluate",["entertain","decorate","advertise"],"Care plan steps.")
H('512.d.7.E',4,"A care plan goal should be realistic and:","measurable",["vague","hidden","random"],"Measurable goals.")
H('512.d.7.F',3,"A nurse checks whether pain medicine worked by reassessing the patient's:","pain level",["height","favorite color","address"],"Evaluate interventions.")
H('512.d.7.F',4,"Turning a bed-bound patient regularly is an intervention to prevent pressure:","injuries",["games","songs","parties"],"Prevent pressure injuries.")
H('512.d.7.G',3,"A positive clinical outcome from nursing care is an improved patient:","condition",["address","wage","schedule"],"Outcomes.")
H('512.d.7.G',4,"A nurse compares assessment data over time to see whether a patient is getting:","better or worse",["older only","taller","louder"],"Trend outcomes.")
H('512.d.8.A',3,"The rights of medication administration include right patient, right drug, right dose, right route, right time, right documentation, right reason, and right:","response",["price","color","brand"],"Eight rights.")
H('512.d.8.A',4,"Comparing the name on the wristband with the order before giving medicine confirms the right:","patient",["route","time","dose"],"Right patient.")
H('512.d.8.B',3,"Pharmacodynamics describes what a drug does to the:","body",["bottle","label","shelf"],"Drug effects.")
H('512.d.8.B',4,"The place where a drug attaches in the body to cause an effect is called a:","receptor",["recipe","routine","reminder"],"Receptors.")
H('512.d.8.C',3,"Pharmacokinetics describes how the body absorbs, distributes, metabolizes, and excretes a:","drug",["meal","book","song"],"ADME.")
H('512.d.8.C',4,"Most drugs are broken down by the liver and removed by the:","kidneys",["eyes","hair","teeth"],"Metabolism and excretion.")
H('512.d.8.D',3,"A drug taken by mouth is given by the oral route, which is convenient and usually:","painless",["painful","expensive","impossible"],"Oral route advantage.")
H('512.d.8.D',4,"A drug given directly into a vein reaches the blood:","immediately",["slowly","never","after a day"],"IV route advantage.")
H('512.d.8.E',3,"A disadvantage of the oral route is that it cannot be used when a patient is vomiting or:","unconscious",["awake","hungry","happy"],"Oral disadvantage.")
H('512.d.8.E',4,"A disadvantage of injections is that they can cause pain and the risk of:","infection",["boredom","fashion","delays only"],"Injection disadvantage.")

# ---- 553 Practicum / Health Science Foundations ----
H('553.d.1.A',3,"A student reviews patient data from charts, labs, and observations before drawing a conclusion. This is interpreting information from various:","sources",["recipes","songs","menus"],"Interpret data.")
H('553.d.1.A',4,"When two sources give different information about a patient, the student should check which source is more:","reliable",["colorful","popular","expensive"],"Reliability.")
H('553.d.1.B',3,"A technical report in health science should be organized, accurate, and based on information collected from several:","sources",["jokes","rumors","songs"],"Technical report.")
H('553.d.1.B',4,"Giving credit for the ideas and data used in a report is done by citing your:","sources",["friends","hobbies","pets"],"Citations.")
H('553.d.1.C',3,"Before giving a presentation, a student should plan it, prepare visuals, and:","practice",["skip","hide","delay"],"Presentation prep.")
H('553.d.1.C',4,"Good presenters know their audience and match the level of detail to the audience's:","needs",["shoe size","hair","pets"],"Know the audience.")
H('553.d.1.D',3,"Extreme heat, cold, and humidity are environmental factors that can disturb the body's:","homeostasis",["wardrobe","budget","schedule"],"Environmental effects.")
H('553.d.1.D',4,"Shivering in cold weather is the body's way to maintain a stable internal:","temperature",["color","height","voice"],"Thermoregulation.")
H('553.d.1.E',3,"The tiny air sacs in the lungs are shaped to allow easy exchange of:","gases",["foods","songs","coins"],"Structure relates to function.")
H('553.d.1.E',4,"The structure of red blood cells, which are thin and flexible, helps them carry:","oxygen",["sound","light","electricity"],"Structure-function.")
H('553.d.1.F',3,"A heart that beats irregularly is an example of atypical:","physiology",["geography","fashion","history"],"Atypical physiology.")
H('553.d.1.F',4,"A curved spine that is not typical in shape is an example of atypical:","anatomy",["grammar","music","history"],"Atypical anatomy.")
H('553.d.2.A',3,"A health care worker should report patient information accurately and follow the facility's:","policies",["jokes","hobbies","decorations"],"Facility reporting.")
H('553.d.2.A',4,"If a student notices a change in a patient's condition, the student should report it to the supervising:","nurse",["visitor","vendor","neighbor"],"Report changes.")
H('553.d.2.B',3,"Listening carefully and responding with empathy is an example of therapeutic:","communication",["distraction","argument","denial"],"Therapeutic communication.")
H('553.d.2.B',4,"Using open-ended questions such as 'How are you feeling?' encourages patients to:","share more",["stay silent","leave","sleep"],"Open-ended questions.")
H('553.d.2.C',3,"A patient who cannot hear well may need the caregiver to face them and speak:","clearly",["quickly","angrily","quietly"],"Barriers.")
H('553.d.2.C',4,"If a patient and caregiver speak different languages, the best solution is to use a qualified:","interpreter",["mascot","gift","map"],"Language barrier.")
